cd /workspace && python3 - <<'PY'
# Load reference definitions up to the fuzz driver.
src=open('/tmp/ref_fuzz.py').read().split('\nbad=0')[0]
ns={}
exec(compile(src,'/tmp/ref_defs.py','exec'),ns)
import json,subprocess,sys,random
make_case=ns['make_case'];Ref=ns['Ref']
for batch in range(20):
    streams=[];expected=[]
    for k in range(8):
        topo,S,ev=make_case(10000+batch*8+k)
        streams.append({'topology':topo,'settings':S,'events':ev})
        expected.append({'events':Ref(topo,S).replay(ev)})
    req={'streams':streams}
    data=json.dumps(req,separators=(',',':')).encode()
    p=subprocess.run([sys.executable,'-B','-u','submission/main.py'],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode!=0:
        print('nonzero',batch,p.stderr[:500]);break
    got=json.loads(p.stdout)
    if got!={'streams':expected}:
        print('MISMATCH batch',batch)
        for i,(a,b) in enumerate(zip(got['streams'],expected)):
            if a!=b:
                print('stream',i)
                print('got',json.dumps(a)[:2000]);print('exp',json.dumps(b)[:2000]);break
        open('/tmp/failreq.json','wb').write(data)
        break
else:
    print('all wire batches okay')
PY
